def P(id, name, rarity, core, wing, theme, why, right=None, harness=None):
    return dict(id=id, name=name, rarity=rarity, core=core, left=wing, right=right or wing,
                harness=harness or {"Rare": "iron_harness", "Épique": "gilded_harness",
                                    "Légendaire": "radiant_harness", "Mythique": "fury_saddle"}[rarity],
                theme=theme, why=why)


